-- MS AUTO DETAILS — execute uma vez no SQL Editor do Supabase.
begin;
create extension if not exists pgcrypto;
-- Authorization is checked inside PostgreSQL, never only in the interface.
create table if not exists ms_admin_users(user_id uuid primary key references auth.users(id) on delete cascade);
alter table ms_admin_users enable row level security;
revoke all on table ms_admin_users from public,anon,authenticated;
revoke create on schema public from public,anon,authenticated;
create or replace function ms_is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$
 select exists(select 1 from public.ms_admin_users where user_id=auth.uid());
$$;
create or replace function ms_require_admin() returns void language plpgsql security definer set search_path=public,pg_temp as $$
begin
 if not public.ms_is_admin() then raise exception 'Acesso permitido somente ao administrador.' using errcode='42501'; end if;
end$$;
revoke all on function ms_is_admin(),ms_require_admin() from public,anon,authenticated;
grant execute on function ms_is_admin() to authenticated;

create table if not exists clients(id bigint generated by default as identity primary key,name text not null,phone text not null default '',address text not null default '',notes text not null default '');
create table if not exists services(id bigint generated by default as identity primary key,name text not null,category text not null,price_cents integer check(price_cents is null or price_cents>=0));
create table if not exists service_catalog_state(id integer primary key,initialized_at timestamptz not null default now());
create table if not exists quotes(id bigint generated by default as identity primary key,client_id bigint references clients,date date not null,valid_until date,calculation jsonb,client text not null,phone text not null default '',service text not null,amount_cents integer not null check(amount_cents>=0),status text not null default 'pendente' check(status in('pendente','aprovado','recusado')),notes text not null default '',public_token uuid not null default gen_random_uuid() unique,public_responded_at timestamptz,created_at timestamptz not null default now());
create table if not exists appointments(id bigint generated by default as identity primary key,client_id bigint references clients,quote_id bigint unique references quotes,completed_date date,date date not null,time time not null,duration_minutes integer not null default 60 check(duration_minutes between 15 and 1440),client text not null,phone text not null default '',location text not null default '',service text not null,amount_cents integer not null check(amount_cents>=0),status text not null default 'agendado' check(status in('agendado','concluido','cancelado')),notes text not null default '',created_at timestamptz not null default now());
create table if not exists incomes(id bigint generated by default as identity primary key,client_id bigint references clients,quote_id bigint unique references quotes,appointment_id bigint unique references appointments,date date not null,client text not null,service text not null,amount_cents integer not null check(amount_cents>=0),payment_method text not null default 'pix',status text not null default 'recebido' check(status in('recebido','pendente','cancelado')),notes text not null default '',created_at timestamptz not null default now());
create table if not exists expenses(id bigint generated by default as identity primary key,date date not null,description text not null,category text not null,amount_cents integer not null check(amount_cents>=0),payment_method text not null default 'pix',notes text not null default '',created_at timestamptz not null default now());
create table if not exists products(id bigint generated by default as identity primary key,name text not null,unit text not null check(unit in('ml','g','un')),stock_milli bigint not null default 0 check(stock_milli>=0),stock_value_cents integer not null default 0 check(stock_value_cents>=0),minimum_milli bigint not null default 0 check(minimum_milli>=0));
create table if not exists stock_entries(id uuid primary key,product_id bigint not null references products,date date not null,quantity_milli bigint not null check(quantity_milli>0),cost_cents integer not null check(cost_cents>=0),expense_id bigint unique references expenses,mode text not null check(mode in('purchase','existing','opening')),created_at timestamptz not null default now());
create table if not exists product_usage(id uuid primary key,product_id bigint not null references products,appointment_id bigint not null references appointments,product_name text not null,unit text not null,date date not null,quantity_milli bigint not null check(quantity_milli>0),cost_cents integer not null check(cost_cents>=0),reversed boolean not null default false,created_at timestamptz not null default now());
create table if not exists job_costs(id uuid primary key,appointment_id bigint not null references appointments,expense_id bigint references expenses,description text not null,amount_cents integer not null check(amount_cents>0),created_at timestamptz not null default now());
create table if not exists work_orders(appointment_id bigint primary key references appointments,item_description text not null default '',condition_notes text not null default '',checklist jsonb not null default '[]'::jsonb);
create table if not exists job_photos(id uuid primary key,appointment_id bigint not null references appointments,stage text not null check(stage in('before','after')),object_key text not null unique,content_type text not null,size integer not null,created_at timestamptz not null default now());
create index if not exists idx_quotes_date on quotes(date);create index if not exists idx_appointments_date_time on appointments(date,time);create index if not exists idx_incomes_date on incomes(date);create index if not exists idx_expenses_date on expenses(date);create index if not exists idx_usage_job on product_usage(appointment_id);create index if not exists idx_job_costs_job on job_costs(appointment_id);create index if not exists idx_client_history on quotes(client_id,date);

insert into service_catalog_state(id) values(1) on conflict do nothing;
insert into services(name,category,price_cents)
select v.name,v.category,null from (values
('Lavagem externa','Lavagem e estética automotiva'),('Limpeza interna','Lavagem e estética automotiva'),('Lavagem completa','Lavagem e estética automotiva'),('Lavagem detalhada','Lavagem e estética automotiva'),('Proteção e acabamento','Lavagem e estética automotiva'),('Higienização de bancos automotivos','Lavagem e estética automotiva'),('Revitalização de faróis','Lavagem e estética automotiva'),
('Sofá 2 lugares','Higienização de sofás'),('Sofá 3 lugares','Higienização de sofás'),('Sofá 4 lugares','Higienização de sofás'),('Sofá 5 lugares','Higienização de sofás'),('Sofá de canto','Higienização de sofás'),('Sofá retrátil','Higienização de sofás'),('Sofá modular','Higienização de sofás'),('Sofá-cama','Higienização de sofás'),
('Higienização de poltrona','Poltronas e cadeiras'),('Higienização de cadeira estofada','Poltronas e cadeiras'),('Higienização de puff','Poltronas e cadeiras'),('Higienização de banco estofado','Poltronas e cadeiras'),
('Higienização de colchão solteiro','Colchões'),('Higienização de colchão casal','Colchões'),('Higienização de colchão queen','Colchões'),('Higienização de colchão king','Colchões'),
('Higienização de almofadas','Outros estofados'),('Higienização de cabeceira estofada','Outros estofados'),('Higienização de bancos automotivos avulsos','Outros estofados')) as v(name,category)
where not exists(select 1 from services);

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('job-photos','job-photos',false,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=false,file_size_limit=5242880,allowed_mime_types=excluded.allowed_mime_types;

alter table clients enable row level security;alter table services enable row level security;alter table quotes enable row level security;alter table appointments enable row level security;alter table incomes enable row level security;alter table expenses enable row level security;alter table products enable row level security;alter table stock_entries enable row level security;alter table product_usage enable row level security;alter table job_costs enable row level security;alter table work_orders enable row level security;alter table job_photos enable row level security;

create or replace function ms_services() returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform ms_require_admin();
 return jsonb_build_object('initialized',true,'services',coalesce((select jsonb_agg(to_jsonb(s) order by id) from services s),'[]'::jsonb));
end$$;

create or replace function ms_dashboard(p_month text default null) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare first_day date;next_day date;begin perform ms_require_admin();
 if p_month is not null then first_day=(p_month||'-01')::date;next_day=first_day+interval '1 month';end if;
 return jsonb_build_object(
 'incomes',coalesce((select jsonb_agg(to_jsonb(x) order by date desc,id desc) from(select i.*,case when status='recebido' then amount_cents else 0 end paid_cents,false has_payments from incomes i where p_month is null or(i.date>=first_day and i.date<next_day) limit 300)x),'[]'::jsonb),
 'expenses',coalesce((select jsonb_agg(to_jsonb(x) order by date desc,id desc) from(select * from expenses where p_month is null or(date>=first_day and date<next_day) limit 300)x),'[]'::jsonb),
 'appointments',coalesce((select jsonb_agg(to_jsonb(x) order by date desc,time desc) from(select a.*,(select id from incomes i where i.appointment_id=a.id)income_id from appointments a where p_month is null or(a.date>=first_day and a.date<next_day) limit 300)x),'[]'::jsonb),
 'quotes',coalesce((select jsonb_agg(to_jsonb(x) order by date desc,id desc) from(select q.*,(select id from incomes i where i.quote_id=q.id)income_id,(select id from appointments a where a.quote_id=q.id)appointment_id,(q.status='recusado' and not exists(select 1 from appointments a where a.quote_id=q.id and a.status<>'cancelado') and not exists(select 1 from incomes i where i.quote_id=q.id and i.status<>'cancelado'))can_delete_cancelled from quotes q where p_month is null or(q.date>=first_day and q.date<next_day) limit 300)x),'[]'::jsonb));end$$;

create or replace function ms_query(p_action text,p_data jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare result jsonb;month_start date;month_end date;rid bigint;begin perform ms_require_admin();
 if p_action='catalog' then return jsonb_build_object('clients',coalesce((select jsonb_agg(to_jsonb(c) order by name)from clients c),'[]'::jsonb),'products',coalesce((select jsonb_agg(to_jsonb(p)order by name)from products p),'[]'::jsonb));end if;
 if p_action='financial' then month_start=((p_data->>'month')||'-01')::date;month_end=month_start+interval '1 month';return jsonb_build_object('received_cents',coalesce((select sum(amount_cents)from incomes where status='recebido'and date>=month_start and date<month_end),0),'received_count',(select count(*)from incomes where status='recebido'and date>=month_start and date<month_end),'spent_cents',coalesce((select sum(amount_cents)from expenses where date>=month_start and date<month_end),0),'expense_count',(select count(*)from expenses where date>=month_start and date<month_end),'pending_cents',coalesce((select sum(amount_cents)from incomes where status='pendente'and date>=month_start and date<month_end),0),'chart',(select jsonb_agg(jsonb_build_object('month',to_char(m,'Mon'),'ganhos',coalesce((select sum(amount_cents)/100.0 from incomes where status='recebido'and date>=m and date<m+interval'1 month'),0),'despesas',coalesce((select sum(amount_cents)/100.0 from expenses where date>=m and date<m+interval'1 month'),0)))from generate_series(month_start-interval'5 months',month_start,interval'1 month')m));end if;
 if p_action='profits' then month_start=((p_data->>'month')||'-01')::date;return coalesce((select jsonb_agg(to_jsonb(x)order by date desc,id desc)from(select a.id,a.date,a.client,a.service,a.status,a.amount_cents,coalesce((select sum(cost_cents)from product_usage u where u.appointment_id=a.id and not reversed),0)product_cost_cents,coalesce((select sum(amount_cents)from job_costs c where c.appointment_id=a.id),0)other_cost_cents from appointments a where a.date>=month_start and a.date<month_start+interval'1 month')x),'[]'::jsonb);end if;
 if p_action='photo' then return (select to_jsonb(p)from job_photos p where id=(p_data->>'id')::uuid);end if;
 rid=case when coalesce(p_data->>'id','') ~ '^[0-9]+$' then (p_data->>'id')::bigint else null end;
 if p_action='client_history' then return coalesce((select jsonb_agg(to_jsonb(x)order by date desc,id desc)from(select'quotes'resource,id,date,service,amount_cents,status from quotes where client_id=rid union all select'appointments',id,date,service,amount_cents,status from appointments where client_id=rid union all select'incomes',id,date,service,amount_cents,status from incomes where client_id=rid)x),'[]'::jsonb);end if;
 if p_action='payments' then return '[]'::jsonb;end if;
 if p_action='calendar' then return coalesce((select jsonb_agg(to_jsonb(x)order by date,time)from(select a.*,(select id from incomes i where i.appointment_id=a.id)income_id from appointments a where a.date>=(p_data->>'start')::date and a.date<(p_data->>'end')::date)x),'[]'::jsonb);end if;
 if p_action='stock_history' then return coalesce((select jsonb_agg(to_jsonb(e)order by date desc,created_at desc)from stock_entries e where product_id=rid),'[]'::jsonb);end if;
 if p_action='job' then return jsonb_build_object('usage',coalesce((select jsonb_agg(to_jsonb(u)order by created_at desc)from product_usage u where appointment_id=rid),'[]'::jsonb),'costs',coalesce((select jsonb_agg(to_jsonb(c)order by created_at desc)from job_costs c where appointment_id=rid),'[]'::jsonb),'work_order',(select to_jsonb(w)from work_orders w where appointment_id=rid),'photos',coalesce((select jsonb_agg(to_jsonb(p)order by created_at)from job_photos p where appointment_id=rid),'[]'::jsonb));end if;
 raise exception 'Consulta inválida.';end$$;

create or replace function ms_public_quote(p_token uuid) returns jsonb language sql security definer set search_path=public,pg_temp as $$select jsonb_build_object('id',q.id,'date',q.date,'valid_until',q.valid_until,'client',q.client,'service',q.service,'amount_cents',q.amount_cents,'calculation',q.calculation,'status',q.status,'responded_at',q.public_responded_at)from quotes q where q.public_token=p_token$$;
create or replace function ms_respond_quote(p_token uuid,p_decision text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare q quotes;begin if p_decision not in('aprovado','recusado')then raise exception'Decisão inválida.';end if;select*into q from quotes where public_token=p_token for update;if not found then raise exception'Orçamento não encontrado.';end if;if q.public_responded_at is not null or q.status<>'pendente'then raise exception'Este orçamento já foi respondido.';end if;if q.valid_until is not null and q.valid_until<current_date then raise exception'Este orçamento venceu. Fale com a MS AUTO DETAILS.';end if;update quotes set status=p_decision,public_responded_at=now()where id=q.id;if p_decision='recusado'then update incomes set status='cancelado'where quote_id=q.id and status='pendente';end if;return ms_public_quote(p_token);end$$;

-- Recompute saved totals in PostgreSQL; supplied subtotals and totals are ignored.
create or replace function ms_quote_pricing(c jsonb) returns jsonb language plpgsql set search_path=public,pg_temp as $$
declare item jsonb;items jsonb:='[]';subtotal bigint:=0;qty integer;price integer;travel integer:=coalesce((c->>'travelCents')::integer,0);extra integer:=coalesce((c->>'extraCents')::integer,0);dv integer:=coalesce((c->'discount'->>'value')::integer,0);dt text:=coalesce(c->'discount'->>'type','fixed');discount_cents bigint;total bigint;description text;summary text:='';
begin
 if jsonb_typeof(c->'items') is distinct from 'array' then raise exception 'Adicione itens ao orçamento.';end if;
 if jsonb_array_length(c->'items') not between 1 and 50 then raise exception 'Use de 1 a 50 itens.';end if;
 for item in select value from jsonb_array_elements(c->'items') loop
  qty=(item->>'quantity')::integer;price=(item->>'unitPriceCents')::integer;description=btrim(item->>'description');
  if qty is null or price is null or description is null or qty not between 1 and 1000 or price not between 0 and 100000000 or length(description) not between 1 and 200 then raise exception 'Item inválido.';end if;
  subtotal=subtotal+qty::bigint*price;
  items=items||jsonb_build_array(jsonb_build_object('description',description,'quantity',qty,'unitPriceCents',price));
  summary=summary||case when summary=''then''else' + 'end||qty||'× '||description;
 end loop;
 total=subtotal+travel+extra;
 if travel<0 or extra<0 or dv<0 or total>100000000 or dt not in('fixed','percent') or(dt='percent'and dv>10000)then raise exception 'Valores inválidos.';end if;
 discount_cents=case when dt='percent'then round(total::numeric*dv/10000)::bigint else dv end;
 if discount_cents>total then raise exception 'Desconto maior que o orçamento.';end if;
 c=jsonb_build_object('items',items,'travelCents',travel,'extraCents',extra,'discount',jsonb_build_object('type',dt,'value',dv),'version',1,'subtotalCents',subtotal,'discountCents',discount_cents,'totalCents',total-discount_cents);
 return jsonb_build_object('calculation',c,'service',summary,'amountCents',total-discount_cents);
end$$;
revoke all on function ms_quote_pricing(jsonb) from public,anon,authenticated;

create or replace function ms_mutate(p_action text,p_data jsonb default '{}'::jsonb) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare d jsonb:=coalesce(p_data->'data','{}'::jsonb);rid bigint:=case when coalesce(p_data->>'id','') ~ '^[0-9]+$' then (p_data->>'id')::bigint else null end;cid bigint;qid bigint;aid bigint;iid bigint;eid bigint;pid bigint;qty bigint;price integer;rec record;op uuid;begin perform ms_require_admin(); perform pg_advisory_xact_lock(9020101); select null::text name,''::text phone,''::text address into rec;
 if nullif(d->>'clientId','')is not null then cid=(d->>'clientId')::bigint;select id,name,phone,address into rec from clients where id=cid;if not found then raise exception'Cliente não encontrado.';end if;end if;
 if p_action='create_incomes'then insert into incomes(client_id,date,client,service,amount_cents,payment_method,status,notes)values(cid,(d->>'date')::date,coalesce(rec.name,d->>'client'),d->>'service',(d->>'amountCents')::integer,coalesce(nullif(d->>'paymentMethod',''),'pix'),case when d->>'status'='pendente'then'pendente'else'recebido'end,coalesce(d->>'notes',''))returning id into rid;return jsonb_build_object('id',rid);end if;
 if p_action='create_expenses'then insert into expenses(date,description,category,amount_cents,payment_method,notes)values((d->>'date')::date,d->>'description',d->>'category',(d->>'amountCents')::integer,coalesce(nullif(d->>'paymentMethod',''),'pix'),coalesce(d->>'notes',''))returning id into rid;return jsonb_build_object('id',rid);end if;
 if p_action='create_appointments'then
  if exists(select 1 from appointments where date=(d->>'date')::date and status<>'cancelado'and time<(d->>'time')::time+make_interval(mins=>coalesce((d->>'durationMinutes')::integer,60))and time+make_interval(mins=>duration_minutes)>(d->>'time')::time)then raise exception'Conflito de horário: já existe um serviço nesse intervalo.';end if;
  insert into appointments(client_id,date,time,duration_minutes,client,phone,location,service,amount_cents,notes)values(cid,(d->>'date')::date,(d->>'time')::time,coalesce((d->>'durationMinutes')::integer,60),coalesce(rec.name,d->>'client'),coalesce(nullif(d->>'phone',''),rec.phone,''),coalesce(nullif(d->>'location',''),rec.address,''),d->>'service',(d->>'amountCents')::integer,coalesce(d->>'notes',''))returning id into aid;
  insert into incomes(client_id,appointment_id,date,client,service,amount_cents,payment_method,status,notes)select client_id,id,date,client,service,amount_cents,'a definir','pendente',notes from appointments where id=aid;return jsonb_build_object('id',aid);end if;
 if p_action='create_quotes'then
  if d->'calculation' is not null and d->'calculation'<>'null'::jsonb then d=d||ms_quote_pricing(d->'calculation');end if;
  insert into quotes(client_id,date,valid_until,calculation,client,phone,service,amount_cents,notes)values(cid,(d->>'date')::date,nullif(d->>'validUntil','')::date,d->'calculation',coalesce(rec.name,d->>'client'),coalesce(nullif(d->>'phone',''),rec.phone,''),d->>'service',(d->>'amountCents')::integer,coalesce(d->>'notes',''))returning id into qid;
  insert into incomes(client_id,quote_id,date,client,service,amount_cents,payment_method,status,notes)select client_id,id,date,client,service,amount_cents,'a definir','pendente',notes from quotes where id=qid;return jsonb_build_object('id',qid);end if;
 if p_action='update_receivable'then select id into iid from incomes where quote_id=rid;if iid is null then insert into incomes(client_id,quote_id,date,client,service,amount_cents,payment_method,status,notes)select client_id,id,date,client,service,amount_cents,'a definir',case when status='recusado'then'cancelado'else'pendente'end,notes from quotes where id=rid returning id into iid;end if;return jsonb_build_object('id',iid);end if;
 if p_action='update_quotes'then
  if p_data->>'status'='recusado'then if exists(select 1 from incomes where quote_id=rid and status='recebido')or exists(select 1 from appointments where quote_id=rid and status='concluido')then raise exception'Esse orçamento possui pagamento ou serviço concluído.';end if;update quotes set status='recusado'where id=rid;update appointments set status='cancelado'where quote_id=rid and status='agendado';update incomes set status='cancelado'where quote_id=rid and status='pendente';return jsonb_build_object('id',rid);end if;
  if p_data->>'status'<>'aprovado'then raise exception'Status inválido.';end if;if exists(select 1 from appointments where quote_id=rid and status<>'cancelado')then return jsonb_build_object('id',rid);end if;
  d=p_data->'data';if exists(select 1 from appointments where date=(d->>'date')::date and status<>'cancelado'and time<(d->>'time')::time+make_interval(mins=>coalesce((d->>'durationMinutes')::integer,60))and time+make_interval(mins=>duration_minutes)>(d->>'time')::time)then raise exception'Conflito de horário: já existe um serviço nesse intervalo.';end if;
  insert into appointments(quote_id,client_id,date,time,duration_minutes,client,phone,location,service,amount_cents,notes)select id,client_id,(d->>'date')::date,(d->>'time')::time,coalesce((d->>'durationMinutes')::integer,60),client,phone,coalesce(d->>'location',''),service,amount_cents,notes from quotes where id=rid on conflict(quote_id) do update set date=excluded.date,time=excluded.time,duration_minutes=excluded.duration_minutes,location=excluded.location,status='agendado' returning id into aid;update quotes set status='aprovado'where id=rid;update incomes set appointment_id=aid,date=case when status='recebido'then date else(d->>'date')::date end,status=case when status='recebido'then'recebido'else'pendente'end where quote_id=rid;return jsonb_build_object('id',rid);end if;
 if p_action='update_appointments'then
  if p_data->>'status'='cancelado'then if exists(select 1 from incomes where appointment_id=rid and status='recebido')or exists(select 1 from appointments where id=rid and status='concluido')then raise exception'Esse serviço possui pagamento ou já foi concluído.';end if;update appointments set status='cancelado'where id=rid;update incomes set status='cancelado'where appointment_id=rid;update quotes set status='recusado'where id=(select quote_id from appointments where id=rid);return jsonb_build_object('id',rid);end if;
  if p_data->>'status'<>'concluido'then raise exception'Status inválido.';end if;if not exists(select 1 from appointments where id=rid and status<>'cancelado')then raise exception'Serviço cancelado ou não encontrado.';end if;if exists(select 1 from appointments where id=rid and status='concluido')then return jsonb_build_object('id',rid);end if;d=p_data->'data';update appointments set status='concluido',completed_date=(d->>'date')::date where id=rid and status<>'cancelado';if d->>'paymentStatus'='recebido'then update incomes set status='recebido',date=(d->>'date')::date,payment_method=d->>'paymentMethod'where appointment_id=rid and status<>'recebido';else update incomes set status='pendente'where appointment_id=rid and status<>'recebido';end if;return jsonb_build_object('id',rid);end if;
 if p_action='update_incomes'then if p_data->>'status'='recebido'then d=p_data->'data';update incomes set status='recebido',date=(d->>'date')::date,payment_method=d->>'paymentMethod'where id=rid and status='pendente';elsif p_data->>'status'='pendente'then update incomes set status='pendente'where id=rid and status<>'cancelado';else raise exception'Status inválido.';end if;return jsonb_build_object('id',rid);end if;
 if p_action like'delete_%'then
  if p_action='delete_delete_cancelled'then if not exists(select 1 from quotes q where q.id=rid and q.status='recusado'and not exists(select 1 from appointments a where a.quote_id=q.id and a.status<>'cancelado')and not exists(select 1 from incomes i where i.quote_id=q.id and i.status<>'cancelado')and not exists(select 1 from appointments a where a.quote_id=q.id and(exists(select 1 from product_usage u where u.appointment_id=a.id)or exists(select 1 from job_costs c where c.appointment_id=a.id)or exists(select 1 from work_orders w where w.appointment_id=a.id)or exists(select 1 from job_photos p where p.appointment_id=a.id))))then raise exception'Orçamento com histórico não pode ser excluído.';end if;delete from incomes where quote_id=rid;delete from appointments where quote_id=rid;delete from quotes where id=rid;return'{}';end if;
  if p_action='delete_expenses'then if exists(select 1 from stock_entries where expense_id=rid)or exists(select 1 from job_costs where expense_id=rid)then raise exception'Despesa vinculada não pode ser excluída.';end if;delete from expenses where id=rid;return'{}';end if;
  if p_action='delete_incomes'then delete from incomes where id=rid and quote_id is null and appointment_id is null;elsif p_action='delete_appointments'then delete from appointments where id=rid and quote_id is null and not exists(select 1 from incomes where appointment_id=rid);elsif p_action='delete_quotes'then delete from quotes where id=rid and not exists(select 1 from incomes where quote_id=rid)and not exists(select 1 from appointments where quote_id=rid);end if;return'{}';end if;
 if p_action='service_create'then if p_data->>'action'='initialize'then return ms_services();end if;d=p_data->'data';insert into services(name,category,price_cents)values(d->>'name',d->>'category',(d->>'priceCents')::integer)returning id into rid;return jsonb_build_object('id',rid);end if;
 if p_action='service_update'then d=p_data->'data';update services set name=d->>'name',category=d->>'category',price_cents=(d->>'priceCents')::integer where id=rid;return jsonb_build_object('id',rid);end if;if p_action='service_delete'then delete from services where id=rid;return'{}';end if;
 if p_action='operation_client'then d=p_data->'data';if rid is null then insert into clients(name,phone,address,notes)values(d->>'name',coalesce(d->>'phone',''),coalesce(d->>'address',''),coalesce(d->>'notes',''))returning id into rid;else update clients set name=d->>'name',phone=coalesce(d->>'phone',''),address=coalesce(d->>'address',''),notes=coalesce(d->>'notes','')where id=rid;end if;return jsonb_build_object('id',rid);end if;
 if p_action='operation_product'then d=p_data->'data';if rid is null then insert into products(name,unit,minimum_milli)values(d->>'name',d->>'unit',(d->>'minimumMilli')::bigint)returning id into rid;else update products set name=d->>'name',minimum_milli=(d->>'minimumMilli')::bigint where id=rid and unit=d->>'unit';end if;return jsonb_build_object('id',rid);end if;
 if p_action='operation_assign_client'then cid=(p_data->>'clientId')::bigint;rid=(p_data->>'id')::bigint;if p_data->>'resource'='quotes'then qid=rid;update quotes set client_id=cid where id=rid;elsif p_data->>'resource'='appointments'then aid=rid;update appointments set client_id=cid where id=rid;select quote_id into qid from appointments where id=rid;else update incomes set client_id=cid where id=rid;select quote_id,appointment_id into qid,aid from incomes where id=rid;end if;update quotes set client_id=cid where id=qid;update appointments set client_id=cid where id=aid or quote_id=qid;update incomes set client_id=cid where appointment_id=aid or quote_id=qid;return'{}';end if;
 if p_action='operation_stock'then d=p_data->'data';op=(d->>'operationId')::uuid;if exists(select 1 from stock_entries where id=op)then return'{}';end if;pid=(d->>'productId')::bigint;qty=(d->>'quantityMilli')::bigint;price=(d->>'costCents')::integer;if d->>'mode'='existing'then eid=(d->>'expenseId')::bigint;if not exists(select 1 from expenses where id=eid and amount_cents=price)or exists(select 1 from stock_entries where expense_id=eid)or exists(select 1 from job_costs where expense_id=eid)then raise exception'Despesa indisponível ou valor diferente.';end if;elsif d->>'mode'='purchase'then insert into expenses(date,description,category,amount_cents,payment_method,notes)select(d->>'date')::date,'Compra de '||name,'Produtos',price,d->>'method','Entrada de estoque'from products where id=pid returning id into eid;end if;insert into stock_entries(id,product_id,date,quantity_milli,cost_cents,expense_id,mode)values(op,pid,(d->>'date')::date,qty,price,eid,d->>'mode');update products set stock_milli=stock_milli+qty,stock_value_cents=stock_value_cents+price where id=pid;return'{}';end if;
 if p_action='operation_consume'then d=p_data->'data';op=(d->>'operationId')::uuid;if exists(select 1 from product_usage where id=op)then return'{}';end if;pid=(d->>'productId')::bigint;aid=(d->>'appointmentId')::bigint;qty=(d->>'quantityMilli')::bigint;select round(stock_value_cents::numeric*qty/stock_milli)::integer into price from products where id=pid and stock_milli>=qty for update;if price is null then raise exception'Estoque insuficiente.';end if;insert into product_usage(id,product_id,appointment_id,product_name,unit,date,quantity_milli,cost_cents)select op,id,aid,name,unit,(d->>'date')::date,qty,price from products where id=pid;update products set stock_milli=stock_milli-qty,stock_value_cents=stock_value_cents-price where id=pid;return'{}';end if;
 if p_action='operation_reverse_usage'then op=(p_data->>'id')::uuid;select*into rec from product_usage where id=op and not reversed for update;if found then update products set stock_milli=stock_milli+rec.quantity_milli,stock_value_cents=stock_value_cents+rec.cost_cents where id=rec.product_id;update product_usage set reversed=true where id=op;end if;return'{}';end if;
 if p_action='operation_job_cost'then d=p_data->'data';op=(d->>'operationId')::uuid;if exists(select 1 from job_costs where id=op)then return'{}';end if;aid=(d->>'appointmentId')::bigint;price=(d->>'amountCents')::integer;if d->>'mode'='existing'then eid=(d->>'expenseId')::bigint;if coalesce((select amount_cents-coalesce((select sum(amount_cents)from job_costs where expense_id=eid),0)from expenses where id=eid),0)<price or exists(select 1 from stock_entries where expense_id=eid)then raise exception'Despesa sem saldo disponível.';end if;else insert into expenses(date,description,category,amount_cents,payment_method,notes)values((d->>'date')::date,d->>'description','Serviço',price,d->>'method','Custo vinculado ao serviço')returning id into eid;end if;insert into job_costs(id,appointment_id,expense_id,description,amount_cents)values(op,aid,eid,d->>'description',price);return'{}';end if;
 if p_action='operation_work_order'then rid=(p_data->>'id')::bigint;d=p_data->'data';insert into work_orders(appointment_id,item_description,condition_notes,checklist)values(rid,coalesce(d->>'itemDescription',''),coalesce(d->>'conditionNotes',''),coalesce(d->'checklist','[]'::jsonb))on conflict(appointment_id)do update set item_description=excluded.item_description,condition_notes=excluded.condition_notes,checklist=excluded.checklist;return'{}';end if;
 if p_action='operation_photo_add'then d=p_data->'data';if (select count(*)from job_photos where appointment_id=(d->>'appointmentId')::bigint)>=12 or (d->>'size')::integer not between 12 and 5242880 or d->>'contentType' not in('image/jpeg','image/png','image/webp') or d->>'objectKey'<>((d->>'appointmentId')||'/'||(d->>'id')) then raise exception'Confira a foto e o limite de 12 fotos por serviço.';end if;insert into job_photos(id,appointment_id,stage,object_key,content_type,size)values((d->>'id')::uuid,(d->>'appointmentId')::bigint,d->>'stage',d->>'objectKey',d->>'contentType',(d->>'size')::integer);return'{}';end if;
 if p_action='operation_photo_delete'then delete from job_photos where id=(p_data->>'id')::uuid;return'{}';end if;
 raise exception'Operação inválida: %',p_action;end$$;

revoke all on function ms_public_quote(uuid) from public;revoke all on function ms_respond_quote(uuid,text) from public;revoke all on function ms_services() from public;revoke all on function ms_dashboard(text) from public;revoke all on function ms_query(text,jsonb) from public;revoke all on function ms_mutate(text,jsonb) from public;grant execute on function ms_public_quote(uuid),ms_respond_quote(uuid,text) to anon,authenticated,service_role;grant execute on function ms_services(),ms_dashboard(text),ms_query(text,jsonb),ms_mutate(text,jsonb) to authenticated;

alter table service_catalog_state enable row level security;
revoke all on table clients,services,service_catalog_state,quotes,appointments,incomes,expenses,products,stock_entries,product_usage,job_costs,work_orders,job_photos from public,anon,authenticated;
drop policy if exists ms_photos_read on storage.objects;
drop policy if exists ms_photos_insert on storage.objects;
drop policy if exists ms_photos_delete on storage.objects;
create policy ms_photos_read on storage.objects for select to authenticated using(bucket_id='job-photos' and (select public.ms_is_admin()));
create policy ms_photos_insert on storage.objects for insert to authenticated with check(bucket_id='job-photos' and (select public.ms_is_admin()));
create policy ms_photos_delete on storage.objects for delete to authenticated using(bucket_id='job-photos' and (select public.ms_is_admin()));
commit;
